fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // tol is strictly positive by assumption
    // Compute difference as i16 to avoid overflow
    // Then check if difference is strictly between -tol and +tol (open interval)
    let diff = (a as i16) - (b as i16);
    let tol_i16 = tol as i16;
    diff > -tol_i16 && diff < tol_i16
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Both vectors have equal, positive lengths by assumption
    // For each pair, use is_close_i8 to test closeness under strict tolerance
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| is_close_i8(x, y, tol))
        .collect()
}